// M8.T10 step 1 (R-205 AC3, NFR-D7; P-platform-07 leftover list, Pearcleaner reference only): the single source of
// every place AntiChat keeps data. Settings › Storage lists it, Remove everything and Uninstall delete it, and
// `tools/ci/zero-files.sh` checks it after removal (`tools/ci/antichat-paths.txt`, generated by `tools/ci/gen-paths.py`
// from the `// path:` lines below; `gen-paths.py --check` fails when the two differ).
// DEBUG: `ANTICHAT_ROOT=<dir>` prefixes every `~/…` path (and the temp dir), so Remove everything can run against a
// scratch tree on this Mac; `-ANTICHAT_DEV_CONTAINER` moves the container as everywhere else.
import AntiChatFoundation
import AntiChatStorage
import Foundation

public struct DataPaths: Sendable, Equatable {
    public enum Kind: String, Sendable, CaseIterable, Codable {
        case container, caches, logs, models, modelsInternal, preferences, savedState, httpStorages, webKit,
             fileToolsContainers, crashReports, incognitoTemp,
             /// M10 (VM release smoke): the system caches named after the bundle ids — URLSession's default cache,
             /// Sparkle's update staging (org.sparkle-project.Sparkle), the engine helpers' caches.
             bundleCaches
    }

    /// One documented location. `pattern` (a `*` glob of the last component) marks leftovers matched by name.
    public struct Entry: Sendable, Equatable, Hashable, Identifiable {
        public var kind: Kind
        public var url: URL
        public var pattern: String?
        public var id: String { url.path + (pattern ?? "") }
        public var displayPath: String { (pattern.map { url.appendingPathComponent($0).path } ?? url.path) }
    }

    public var bundleID: String
    public var home: URL
    public var container: URL
    public var caches: URL
    public var logs: URL
    public var models: URL
    public var tmp: URL

    /// `~/…` and `$TMPDIR/…` for display (the documented form; the same on every Mac).
    public func display(_ path: String) -> String {
        let t = tmp.standardizedFileURL.path, h = home.standardizedFileURL.path
        if path.hasPrefix(t + "/") || path == t { return "$TMPDIR" + path.dropFirst(t.count) }
        if path.hasPrefix(h + "/") { return "~" + path.dropFirst(h.count) }
        return path
    }
    /// DEBUG `ANTICHAT_ROOT` run: a scratch tree. Removal then never touches this Mac's real defaults domain, login
    /// item, shortcuts or Keychain items (only `ANTICHAT_KEYCHAIN_PREFIX` ones).
    public var isScratch = false
    /// Review fix (M8.T16): a Debug build on a Mac that also has the Release app's data leaves what both builds share
    /// (the `Caches/AntiChat` folder, the FileTools containers, `AntiChat*.ips` crash reports, `app.antichat.*`
    /// Keychain items) to the Release app: a Debug Remove everything / Uninstall never deletes the owner's real data.
    public var keepsReleaseShared = false

    public static let releaseBundleID = "app.antichat.AntiChat"
    public static let keychainPrefix = "app.antichat."

    public init(bundleID: String, home: URL, container: URL, caches: URL, logs: URL, models: URL, tmp: URL) {
        self.bundleID = bundleID; self.home = home; self.container = container; self.caches = caches; self.logs = logs
        self.models = models; self.tmp = tmp
    }

    /// The paths of this process: the real home (or `ANTICHAT_ROOT` in DEBUG), the app's container, the Models folder
    /// where it is now (`ModelsFolderLocation`), Debug and Release names kept apart (`AntiChat-Dev`).
    public static func current(environment: [String: String] = ProcessInfo.processInfo.environment,
                               options: LaunchOptions = .current, debug: Bool = AppDatabaseFlags.isDebugBuild,
                               defaults: UserDefaults = AppDefaults.standard) -> DataPaths {
        var home = FileManager.default.homeDirectoryForCurrentUser
        var tmp = URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
        var rooted = false
        #if DEBUG || ANTICHAT_PERF_HARNESS
        if let r = environment["ANTICHAT_ROOT"], !r.isEmpty {
            home = URL(fileURLWithPath: r, isDirectory: true)
            tmp = home.appendingPathComponent("tmp", isDirectory: true)
            rooted = true
        }
        #endif
        let name = AppDatabase.defaultContainerName(debug: debug)
        let container: URL
        if let dev = options.devContainer {
            container = URL(fileURLWithPath: dev, isDirectory: true)
        } else {
            container = home.appendingPathComponent("Library/Application Support/\(name)", isDirectory: true)
        }
        let bundle = debug ? releaseBundleID + ".dev" : releaseBundleID
        let modelsDefault = container.appendingPathComponent("Models", isDirectory: true)
        var models = rooted ? modelsDefault : (ModelsFolderLocation(defaults: defaults).resolve().movedURL ?? modelsDefault)
        #if DEBUG || ANTICHAT_PERF_HARNESS
        if rooted, let m = environment["ANTICHAT_MODELS_FOLDER"], !m.isEmpty { models = URL(fileURLWithPath: m, isDirectory: true) }
        #endif
        var p = DataPaths(bundleID: bundle, home: home, container: container,
                          caches: home.appendingPathComponent("Library/Caches/AntiChat", isDirectory: true),
                          logs: home.appendingPathComponent("Library/Logs/\(name)", isDirectory: true),
                          models: models, tmp: tmp)
        p.isScratch = rooted
        let releaseContainer = home.appendingPathComponent("Library/Application Support/\(AppDatabase.defaultContainerName(debug: false))")
        p.keepsReleaseShared = debug && !rooted && FileManager.default.fileExists(atPath: releaseContainer.path)
        return p
    }

    /// The Models folder is inside the container unless the user moved it (then it is listed on its own).
    public var modelsAreInsideContainer: Bool { models.standardizedFileURL.path.hasPrefix(container.standardizedFileURL.path + "/") }
    public var modelsInternal: URL { container.appendingPathComponent("Models-internal", isDirectory: true) }

    /// Every documented location, in display order.
    public var entries: [Entry] {
        let lib = home.appendingPathComponent("Library", isDirectory: true)
        var out: [Entry] = [
            Entry(kind: .container, url: container),  // path: ~/Library/Application Support/AntiChat
            Entry(kind: .caches, url: caches),  // path: ~/Library/Caches/AntiChat
            Entry(kind: .logs, url: logs),  // path: ~/Library/Logs/AntiChat
        ]
        if !modelsAreInsideContainer { out.append(Entry(kind: .models, url: models)) }  // path: <moved Models folder>
        out += [
            Entry(kind: .preferences, url: lib.appendingPathComponent("Preferences/\(bundleID).plist")),  // path: ~/Library/Preferences/app.antichat.AntiChat.plist
            Entry(kind: .savedState, url: lib.appendingPathComponent("Saved Application State/\(bundleID).savedState", isDirectory: true)),  // path: ~/Library/Saved Application State/app.antichat.AntiChat.savedState
            Entry(kind: .httpStorages, url: lib.appendingPathComponent("HTTPStorages", isDirectory: true), pattern: "\(bundleID)*"),  // path: ~/Library/HTTPStorages/app.antichat.AntiChat*
            Entry(kind: .webKit, url: lib.appendingPathComponent("WebKit/\(bundleID)", isDirectory: true)),  // path: ~/Library/WebKit/app.antichat.AntiChat
            Entry(kind: .bundleCaches, url: lib.appendingPathComponent("Caches", isDirectory: true), pattern: "\(bundleID)*"),  // path: ~/Library/Caches/app.antichat.AntiChat*
            Entry(kind: .fileToolsContainers, url: lib.appendingPathComponent("Containers", isDirectory: true), pattern: "\(Self.releaseBundleID).FileTools*"),  // path: ~/Library/Containers/app.antichat.AntiChat.FileTools*
            Entry(kind: .crashReports, url: lib.appendingPathComponent("Logs/DiagnosticReports", isDirectory: true), pattern: "AntiChat*.ips"),  // path: ~/Library/Logs/DiagnosticReports/AntiChat*.ips
            Entry(kind: .incognitoTemp, url: tmp, pattern: "AntiChat-incognito-*"),  // path: $TMPDIR/AntiChat-incognito-*
        ]
        if bundleID.hasSuffix(".dev") {
            // The Debug helper's own caches folder (EngineListener.Paths.folderName); Debug builds only.
            out.append(Entry(kind: .caches, url: lib.appendingPathComponent("Caches/AntiChat-Dev", isDirectory: true)))
            // The XPC helpers keep their shipped ids in Debug (`app.antichat.AntiChat.Engine…`), so the `<bundleID>*`
            // pattern above (`….dev*`) misses the caches CFNetwork makes for them (M10.T09 AT-FA-13 sweep).
            out.append(Entry(kind: .bundleCaches, url: lib.appendingPathComponent("Caches", isDirectory: true),
                             pattern: "\(Self.releaseBundleID).Engine*"))
        }
        // The vendored UncaughtExceptionLogger keeps `last-crash-reason.log` in `Logs/AntiChat` whatever the build, so
        // a Debug build lists that folder too (shared with the Release app like `Caches/AntiChat`; M8.T16 Tart run).
        let sharedLogs = lib.appendingPathComponent("Logs/AntiChat", isDirectory: true)
        if logs.standardizedFileURL != sharedLogs.standardizedFileURL { out.append(Entry(kind: .logs, url: sharedLogs)) }
        if keepsReleaseShared {
            out.removeAll {
                ($0.kind == .caches && $0.url == caches) || ($0.kind == .logs && $0.url == sharedLogs)
                    || ($0.kind == .bundleCaches && $0.pattern == "\(Self.releaseBundleID).Engine*")
                    || [.fileToolsContainers, .crashReports].contains($0.kind)
            }
        }
        return out
    }

    /// The items that exist now: plain entries as themselves, patterns expanded to their matches.
    public func existing(fileManager fm: FileManager = .default) -> [URL] {
        entries.flatMap { e -> [URL] in
            guard let p = e.pattern else { return fm.fileExists(atPath: e.url.path) ? [e.url] : [] }
            return Self.names(in: e.url, matching: p).map { e.url.appendingPathComponent($0) }
        }
    }

    /// VQ (S-21 Storage): what [Show in Finder] selects for a friendly location — its first item that exists (a
    /// pattern expanded), else the folder that would hold it.
    public func revealTarget(_ location: StorageLocation, fileManager fm: FileManager = .default) -> URL {
        if location == .models { return models }
        let mine = entries.filter { StorageLocation.of($0.kind) == location }
        for e in mine {
            if let p = e.pattern {
                if let n = Self.names(in: e.url, matching: p).first { return e.url.appendingPathComponent(n) }
            } else if fm.fileExists(atPath: e.url.path) {
                return e.url
            }
        }
        let first = mine.first.map { $0.pattern == nil ? $0.url.deletingLastPathComponent() : $0.url } ?? container
        return first
    }

    /// The friendly locations this Mac lists (File tools only where its containers are AntiChat's to show).
    public var locations: [StorageLocation] {
        let kinds = Set(entries.map { StorageLocation.of($0.kind) })
        return StorageLocation.allCases.filter { $0 != .models && kinds.contains($0) }
    }

    /// The names in `dir` that match `pattern`, sorted. VQ (S-21 Storage): `readdir` with a byte test of the pattern's
    /// literal head before any Swift String is made. `$TMPDIR` can hold hundreds of thousands of entries (458 k on a
    /// dev Mac); listing it with `contentsOfDirectory` and globbing every name took ~40 s, which kept the Storage
    /// page's size spinner turning in Debug and Release alike.
    public static func names(in dir: URL, matching pattern: String) -> [String] {
        guard let d = opendir(dir.path) else { return [] }
        defer { closedir(d) }
        let head = Array(pattern.prefix { $0 != "*" }.utf8)
        var out: [String] = []
        while let e = readdir(d) {
            let len = Int(e.pointee.d_namlen)
            guard len >= head.count else { continue }
            let starts = withUnsafeBytes(of: e.pointee.d_name) { raw -> Bool in
                head.isEmpty || (0..<head.count).allSatisfy { raw[$0] == head[$0] }
            }
            guard starts else { continue }
            let name = withUnsafeBytes(of: e.pointee.d_name) { raw in
                String(decoding: raw.prefix(len), as: UTF8.self)
            }
            if name != ".", name != "..", matches(name, pattern) { out.append(name) }
        }
        return out.sorted()
    }

    /// `*` glob over one path component (no other wildcard: the list is exact names plus a prefix/suffix).
    public static func matches(_ name: String, _ pattern: String) -> Bool {
        let parts = pattern.split(separator: "*", omittingEmptySubsequences: false).map(String.init)
        guard parts.count > 1 else { return name == pattern }
        guard name.hasPrefix(parts[0]), name.count >= parts.reduce(0, { $0 + $1.count }) else { return false }
        var rest = Substring(name.dropFirst(parts[0].count))
        for (i, part) in parts.dropFirst().enumerated() {
            let last = i == parts.count - 2
            if last { return part.isEmpty || rest.hasSuffix(part) }
            guard let r = rest.range(of: part) else { return false }
            rest = rest[r.upperBound...]
        }
        return true
    }
}

/// M8.T10 step 4–5: where the Models folder lives. Default = `<container>/Models`; after Move… a minimal bookmark plus
/// the path (for the "not connected" notice) in UserDefaults. An unresolvable or unreachable bookmark = drive missing:
/// the app falls back to the starter model kept on the internal disk (`Models-internal`).
public struct ModelsFolderLocation: Sendable {
    public static let bookmarkKey = "modelsFolderBookmark"
    public static let pathKey = "modelsFolderPath"

    public enum State: Sendable, Equatable {
        case standard
        case moved(URL)
        case missing(path: String)

        public var movedURL: URL? { if case .moved(let u) = self { u } else { nil } }
        public var isMissing: Bool { if case .missing = self { true } else { false } }
    }

    nonisolated(unsafe) let defaults: UserDefaults
    public init(defaults: UserDefaults = AppDefaults.standard) { self.defaults = defaults }

    public func resolve() -> State {
        guard let data = defaults.data(forKey: Self.bookmarkKey) else { return .standard }
        let path = defaults.string(forKey: Self.pathKey) ?? ""
        var stale = false
        guard let url = try? URL(resolvingBookmarkData: data, options: [.withoutUI, .withoutMounting], bookmarkDataIsStale: &stale),
              FileManager.default.fileExists(atPath: url.appendingPathComponent("store").path) else {
            return .missing(path: path)
        }
        if stale, let fresh = try? url.bookmarkData(options: .minimalBookmark) { defaults.set(fresh, forKey: Self.bookmarkKey) }
        return .moved(url)
    }

    public func persist(_ url: URL) throws {
        defaults.set(try url.bookmarkData(options: .minimalBookmark), forKey: Self.bookmarkKey)
        defaults.set(url.path, forKey: Self.pathKey)
    }

    /// Back to `<container>/Models` (a Move… to the default path).
    public func reset() {
        defaults.removeObject(forKey: Self.bookmarkKey)
        defaults.removeObject(forKey: Self.pathKey)
    }
}
